export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const basePremium = quote.items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0
  );
  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
  const firstInsuranceSurcharge = basePremium / 10;
  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
  return { results: [{ premium }] };
};
